    private fun dfs(node:Int,parent:Int):IntArray{
        val count=IntArray(26);
        count[labels[node]-'a']=1;
        for(child in graph[node])if(child!=parent){
            val childCount=dfs(child,node);
            for(letter in 0..25)count[letter]+=childCount[letter]
        };
        answer[node]=count[labels[node]-'a'];
        return count
    };
    fun countSubTrees(n:Int,edges:Array<IntArray>,labels:String):IntArray{
        this.labels=labels;
        answer=IntArray(n);
        graph=Array(n){
            mutableListOf<Int>()
        };
        for(edge in edges){
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0])
        };
        dfs(0,-1);
        return answer
    }
}

